def assets():
    out = []
    for shot, (theme, rows) in enumerate(GROUPS, 1):
        for item, (key, name, dimensions, finish, construction) in enumerate(rows, 1):
            out.append(dict(id=f'U{shot:02d}_{item:02d}', key=key, name=name,
                screenshot=shot, theme=theme, planned_dimensions_m=dimensions,
                finish_target=finish, construction=construction,
                source=f'references/screen_{shot:02d}.png',
                stage='geometry_candidate', geometry_approved=False,
                dimension_basis='Оценка по скриншоту; не обмер оригинального предмета',
                axis='X ширина, Y глубина, Z вверх; лицевая сторона -Y; метры',
                unique_design=True))
    return out


def prepare():
    ROOT.mkdir(parents=True, exist_ok=True)
    refs = ROOT / 'references'
    refs.mkdir(exist_ok=True)
    for n, source in enumerate(SOURCES, 1):
        src = Path('C:/Users/SCHECT~1/AppData/Local/Temp') / f'codex-clipboard-{source}.png'
        dst = refs / f'screen_{n:02d}.png'
        if not dst.exists():
            shutil.copy2(src, dst)
    rows = assets()
    assert len(rows) == 95 and len({a['key'] for a in rows}) == 95
    (ROOT / 'manifest.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding='utf-8')
    lines = ['# 95 оригинальных ассетов по 19 кадрам', '',
      'Поручение владельца от 24.10.2026: по пять самостоятельных моделей на каждый кадр. '
      'Назначение — реалистичное окружение RING. Все модели создаются заново в Blender; '
      'в этой партии нет персонажей и оружия. Повторы за счёт цвета или масштаба не считаются отдельными ассетами.', '',
      'Размеры ниже — проектные оценки, а не подтверждённые обмеры изображённых предметов. '
      'Видимые силуэты и материалы сверяются с кадрами; скрытые стороны — авторская конструктивная реконструкция. '
      'Обычные предметы 1:1. Архитектурные проходы учитывают правило E из AGENTS.md: '
      'ширина ×1,3, высота ×1,15 от условного реального прохода; массивные залы не увеличиваются.', '',
      'Текущая стадия: редактируемая геометрия v01 с нейтральными материалами. Производственные UV, '
      'UCUPaint, игровые LOD/коллизии и экспорт ещё не выполнены. По blender-asset-workflow '
      'текстурирование начинается после принятия показанной геометрии. Цветовые слоты служат '
      'только для раздельной будущей отделки; фактура в превью не имитируется.', '',
      'Финишная цель: приглушённый городской PBR — бетон, оцинковка, потёртая краска, '
      'пыльное стекло, ткань и дерево. Исходных карт игры нет: кадры используются как визуальные '
      'референсы, а не извлекаются в текстурные карты. Маркировка и символы — собственные, '
      'бренды и интерфейс со скриншотов не переносятся.', '']
    for shot, (theme, _) in enumerate(GROUPS, 1):
        lines += [f'## Кадр {shot:02d} — {theme}', '',
          '| ID | Модель | Плановый габарит X × Y × Z, м | Конструктивные признаки | Будущие материалы |',
          '|---|---|---|---|---|']
        for a in rows[(shot-1)*5:shot*5]:
            dim = ' × '.join(str(x) for x in a['planned_dimensions_m'])
            lines.append(f"| {a['id']} | {a['name']} | {dim} | {a['construction']} | {a['finish_target']} |")
        lines.append('')
    (PROJECT / 'docs/assets/urban_screens_95_matrix.md').write_text('\n'.join(lines), encoding='utf-8')
    (ROOT / 'license.txt').write_text('Геометрия: оригинальная работа для владельца RING.\n'
      'Референсы: предоставленные владельцем скриншоты Escape from Tarkov; права на игру и снимки '
      'не передаются. Только визуальные референсы, не текстурные карты и не часть игрового экспорта.\n'
      'Сторонние модели и текстуры на стадии геометрии не используются.\n', encoding='utf-8')
    print(f'CATALOG_OK {len(rows)} assets; {ROOT}', flush=True)


if __name__ == '__main__':
    prepare()
